import jsPDF from 'jspdf';

// ─── Embedded logo (transparent PNG base64) ───────────────────────────────────
const LOGO_B64 = 'data:image/png;base64,';

// ─── Page layout (mm) ────────────────────────────────────────────────────────
const PW = 210, PH = 297;
const ML = 10, MR = 10;
const TAB = 22;
const CX  = ML + TAB + 5;
const CCW = PW - CX - MR;

// ─── Palette ──────────────────────────────────────────────────────────────────
const C = {
  bg:      [213, 230, 240],
  white:   [255, 255, 255],
  navy:    [0,   58,  112],
  blue:    [0,   117, 191],
  blueLt:  [232, 242, 250],
  txt:     [26,  43,  60],
  muted:   [90,  122, 154],
  bdr:     [184, 206, 220],
  shad:    [192, 212, 223],
  rdot:    [229, 57,  53],
  sideTab: [0,   43,  96],
};

const STATUS_BG = {
  acceptable: [230, 247, 232],
  caution:    [255, 248, 220],
  alert:      [253, 232, 232],
};
const RISK_BG = {
  low:    [230, 247, 232],
  medium: [255, 248, 220],
  high:   [253, 232, 232],
};

// ─── Primitives ───────────────────────────────────────────────────────────────
const setFill   = (d, [r,g,b]) => d.setFillColor(r,g,b);
const setStroke = (d, [r,g,b]) => d.setDrawColor(r,g,b);

const rr = (d, x, y, w, h, {r=3, fill=null, stroke=null, lw=0.5}={}) => {
  if (lw)     d.setLineWidth(lw);
  if (fill)   setFill(d, fill);
  if (stroke) setStroke(d, stroke);
  d.roundedRect(x, y, w, h, r, r, (fill && stroke) ? 'FD' : fill ? 'F' : 'S');
};

const card = (d, x, y, w, h, r=3) => {
  rr(d, x+0.6, y+0.6, w, h, {r, fill:C.shad});
  rr(d, x, y, w, h, {r, fill:C.white, stroke:C.bdr, lw:0.4});
};

const dot = (d, x, y, r=1.8, col=null) => { setFill(d, col||C.rdot); d.circle(x, y, r, 'F'); };

const tx = (d, s, x, y, {sz=9, bold=false, col=null, align='left'}={}) => {
  d.setFont('helvetica', bold ? 'bold' : 'normal');
  d.setFontSize(sz);
  setFill(d, col||C.txt);
  if (align === 'right')       d.text(String(s??''), x, y, {align:'right'});
  else if (align === 'center') d.text(String(s??''), x, y, {align:'center'});
  else                         d.text(String(s??''), x, y);
};

// ─── Card header strip ────────────────────────────────────────────────────────
const cardHdr = (d, x, y, w, h=9, plain='', bold='') => {
  rr(d, x, y, w, h, {r:3, fill:C.blueLt});
  d.setDrawColor(...C.bdr); d.setLineWidth(0.3); d.line(x, y+h, x+w, y+h);
  dot(d, x+5, y+h/2);
  tx(d, plain, x+10, y+h/2+1, {sz:8.5, col:C.txt});
  const off = plain ? d.getStringUnitWidth(plain+' ') * 8.5 / d.internal.scaleFactor : 0;
  tx(d, bold, x+10+off, y+h/2+1, {sz:8.5, bold:true, col:C.blue});
};

// ─── Info row ─────────────────────────────────────────────────────────────────
const infoRow = (d, x, y, w, label, value, {h=10, bg=null, vc=null}={}) => {
  card(d, x, y, w, h);
  if (bg) rr(d, x, y, w, h, {r:3, fill:bg, stroke:C.bdr, lw:0.4});
  dot(d, x+5, y+h/2);
  tx(d, label, x+10, y+h/2+1, {sz:9, col:C.txt});
  const off = d.getStringUnitWidth(label+' ') * 9 / d.internal.scaleFactor;
  tx(d, value, x+10+off, y+h/2+1, {sz:9, bold:true, col: vc||C.blue});
  return y + h + 2;
};

// ─── Side tab ─────────────────────────────────────────────────────────────────
const sideTab = (d, y, h, label) => {
  rr(d, ML, y, TAB, h, {r:3, fill:C.sideTab});
  d.setFont('helvetica','bold');
  setFill(d, C.white);
  let sz = 9.5;
  const maxW = h - 16;
  while (sz > 5 && d.getStringUnitWidth(label) * sz / d.internal.scaleFactor > maxW) sz -= 0.3;
  d.setFontSize(sz);
  d.text(label, ML + TAB/2, y + h/2, {angle:90, align:'center'});
};

// ─── Image box ────────────────────────────────────────────────────────────────
const imgBox = (d, x, y, w, h, plain, boldLbl, imgData=null) => {
  const HDR = 9;
  card(d, x, y, w, h);
  cardHdr(d, x, y, w, HDR, plain, boldLbl);
  const bx=x+2, by=y+HDR+1.5, bw=w-4, bh=h-HDR-3;
  rr(d, bx, by, bw, bh, {r:2, fill:[236,244,250]});
  if (imgData) {
    try {
      const fmt = imgData.startsWith('data:image/png') ? 'PNG' : 'JPEG';
      d.addImage(imgData, fmt, bx+1, by+1, bw-2, bh-2, undefined, 'FAST');
    } catch(e) {}
  }
};

// ─── Text card ────────────────────────────────────────────────────────────────
const textCard = (d, x, y, w, h, title, body) => {
  const HDR = 9;
  card(d, x, y, w, h);
  cardHdr(d, x, y, w, HDR, '', title);
  let ty = y+HDR+5; const bot=y+h-2, mw=w-7;
  String(body||'').split('\n').forEach(raw => {
    if (ty>bot) return;
    const line=raw.trim();
    if (!line){ty+=2;return;}
    d.setFont('helvetica','normal'); d.setFontSize(7.5); setFill(d,C.txt);
    d.splitTextToSize(line,mw).forEach(wl=>{if(ty<=bot){d.text(wl,x+3.5,ty);ty+=4;}});
    ty+=1;
  });
};

// ─── Bullet card ─────────────────────────────────────────────────────────────
const bulletCard = (d, x, y, w, h, title, body) => {
  const HDR = 9;
  card(d, x, y, w, h);
  cardHdr(d, x, y, w, HDR, '', title);
  let ty=y+HDR+5.5; const bot=y+h-2, mw=w-13;
  String(body||'').split('\n').filter(l=>l.trim()).forEach(line => {
    if (ty>bot) return;
    dot(d, x+6, ty-1, 1.5);
    d.setFont('helvetica','normal'); d.setFontSize(8.5); setFill(d,C.txt);
    d.splitTextToSize(line.trim(),mw).forEach(wl=>{if(ty<=bot){d.text(wl,x+10,ty);ty+=4.5;}});
    ty+=1.5;
  });
};

// ─── HEADER — two rounded boxes on page bg ────────────────────────────────────
const drawHeader = (d, formTitle, formSubtitle) => {
  const HDR    = 38;
  const PAD    = 4;
  const BOX_H  = HDR - PAD * 2;
  const BOX_Y  = PAD;
  const LOGO_W = 50;
  const GAP    = 4;
  const TITLE_X = PAD + LOGO_W + GAP;
  const TITLE_W = PW - TITLE_X - PAD;
  const BOX_BG  = [232, 240, 247];
  const BOX_BDR = [180, 205, 220];

  setFill(d, C.bg); d.rect(0, 0, PW, HDR, 'F');

  // Box 1 — logo (no white bg, transparent logo on box color)
  rr(d, PAD, BOX_Y, LOGO_W, BOX_H, {r:4, fill:BOX_BG, stroke:BOX_BDR, lw:0.5});
  try {
    const lp = 2;
    d.addImage(LOGO_B64, 'PNG', PAD+lp, BOX_Y+lp, LOGO_W-lp*2, BOX_H-lp*2);
  } catch(e) {
    tx(d,'ANDRITZ', PAD+3, BOX_Y+BOX_H*0.55, {sz:10, bold:true, col:C.navy});
  }

  // Box 2 — titles
  rr(d, TITLE_X, BOX_Y, TITLE_W, BOX_H, {r:4, fill:BOX_BG, stroke:BOX_BDR, lw:0.5});
  const cx = TITLE_X + TITLE_W / 2;
  tx(d, formTitle || 'Condition Monitoring Report',
     cx, BOX_Y + BOX_H * 0.44, {sz:15, bold:true, col:C.navy, align:'center'});
  tx(d, formSubtitle || 'Vibration Diagnosis and Recommendation',
     cx, BOX_Y + BOX_H * 0.74, {sz:9, bold:true, col:C.blue, align:'center'});

  d.setDrawColor(...C.bdr); d.setLineWidth(0.5);
  d.line(0, HDR, PW, HDR);
};

// ─── Footer bar ───────────────────────────────────────────────────────────────
const drawFooterBar = (d, tech, date) => {
  const BY=PH-30, h=11, half=(PW-ML-MR-4)/2;
  card(d,ML,BY,half,h);
  dot(d,ML+5,BY+h/2);
  tx(d,'Emitted by ',ML+10,BY+h/2+1,{sz:9,col:C.txt});
  const off=d.getStringUnitWidth('Emitted by ')*9/d.internal.scaleFactor;
  tx(d,tech,ML+10+off,BY+h/2+1,{sz:9,bold:true,col:C.blue});
  const rx=ML+half+4;
  card(d,rx,BY,half,h);
  dot(d,rx+5,BY+h/2);
  tx(d,'Note Date ',rx+10,BY+h/2+1,{sz:9,col:C.txt});
  const off2=d.getStringUnitWidth('Note Date ')*9/d.internal.scaleFactor;
  tx(d,date,rx+10+off2,BY+h/2+1,{sz:9,bold:true,col:C.blue});
};

const drawPageFooter = (d, id) => {
  d.setDrawColor(...C.bdr); d.setLineWidth(0.4); d.line(ML,PH-10,PW-MR,PH-10);
  tx(d,'ANDRITZ Condition Monitoring System  ·  '+id+'  ·  Clearwater Paper  ·  Augusta, GA  ·  CONFIDENTIAL',
    ML,PH-6,{sz:6.5,col:C.muted});
  tx(d,'Page 1',PW-MR,PH-6,{sz:7,bold:true,col:C.muted,align:'right'});
};

// ═══════════════════════════════════════════════════════════════════════════════
// CMR — SINGLE PAGE
// ═══════════════════════════════════════════════════════════════════════════════
export function generateConditionMonitorPDF(data, millName) {
  const d = new jsPDF({unit:'mm',format:'a4',orientation:'portrait'});
  const id = data.cmrNumber
    ? 'CMR-' + data.cmrNumber
    : 'CMR-' + String(Math.floor(Math.random()*900)+100) + '-' + new Date().getFullYear();

  setFill(d,C.bg); d.rect(0,0,PW,PH,'F');
  drawHeader(d, 'Condition Monitoring Report', 'Vibration Diagnosis and Recommendation');

  const ROW_H=10, GAP=2;
  let y = 42;

  const scKey   = (data.statusCondition||'alert').toLowerCase();
  const scBg    = STATUS_BG[scKey] || STATUS_BG.alert;
  const rkKey   = (data.risk||'high').toLowerCase();
  const rkBg    = RISK_BG[rkKey] || RISK_BG.high;
  const scLabel = (data.statusCondition||'Alert').charAt(0).toUpperCase()+(data.statusCondition||'Alert').slice(1);
  const rkLabel = (data.risk||'high').charAt(0).toUpperCase()+(data.risk||'high').slice(1)+' Risk';

  const half  = (CCW-3)/2;
  const third = (CCW-6)/3;
  const genH  = 5*(ROW_H+GAP)+6;
  sideTab(d, y, genH, 'General Information');
  y += 2;

  y = infoRow(d, CX, y, CCW, 'Location:', data.area||'—');
  y = infoRow(d, CX, y, CCW, 'Asset & ID:', (data.assetName||'—')+' - '+(data.assetId||'—'));

  let _y = y;
  infoRow(d, CX,        _y, half, 'Vibration Diagnosis:', data.diagnosis||'—');
  infoRow(d, CX+half+3, _y, half, 'Status Condition:', scLabel, {bg:scBg, vc:C.blue});
  y = _y + ROW_H + GAP;

  _y = y;
  infoRow(d, CX,        _y, half, 'gE Level:', (data.geLevel||'—')+' gE');
  infoRow(d, CX+half+3, _y, half, 'Temperature:', (data.temperature||'—')+' °F');
  y = _y + ROW_H + GAP;

  _y = y;
  infoRow(d, CX,              _y, third, 'Risk:', rkLabel, {bg:rkBg, vc:C.blue});
  infoRow(d, CX+third+3,      _y, third, 'CMR:', data.cmrNumber||'—');
  infoRow(d, CX+(third+3)*2,  _y, third, 'Vibration Level:', (data.vibrationLevel||'—')+' in/s', {bg:scBg, vc:C.blue});
  y = _y + ROW_H + GAP + 8;

  const diagH = PH - y - 32;
  sideTab(d, y, diagH, 'Vibration Diagnosis and Recommendation');
  y += 2;

  const imgHalf = (CCW-4)/2;
  const imgH    = 52;

  imgBox(d, CX,           y, imgHalf, imgH, 'Trend:',    data.trendLabel||'Motor Inboard Envelope', data.trendImage||null);
  imgBox(d, CX+imgHalf+4, y, imgHalf, imgH, 'Spectrum:', data.spectrumLabel||'Frequency Spectrum',  data.spectrumImage||null);
  y += imgH + 4;

  const machH = 58;
  imgBox(d,  CX,           y, imgHalf, machH, 'Machine', 'Image', data.machineImage||null);
  textCard(d, CX+imgHalf+4, y, imgHalf, machH, 'Description', data.observations||'');
  y += machH + 4;

  const recH = Math.max(PH-y-32, 26);
  bulletCard(d, CX, y, CCW, recH, 'Recommendation', data.recommendation||'');

  drawFooterBar(d, data.technicianName||'', data.date||'');
  drawPageFooter(d, id);
  d.save(id+'_Condition_Monitor.pdf');
  return id;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Post Maintenance
// ═══════════════════════════════════════════════════════════════════════════════
export function generatePostMaintenancePDF(data, millName) {
  const d = new jsPDF({unit:'mm',format:'a4'});
  const id = 'PMF-'+String(Math.floor(Math.random()*900)+100)+'-'+new Date().getFullYear();
  setFill(d,C.bg); d.rect(0,0,PW,PH,'F');
  drawHeader(d, 'Post Maintenance Form', 'Maintenance Record & Post-Check Readings');

  const ROW_H=10, GAP=2;
  let y=42, half=(CCW-3)/2, col3=(CCW-6)/3;

  sideTab(d,y,56,'General Information'); y+=2;
  let _y=y;
  infoRow(d,CX,            _y,col3,'Date:',       data.maintenanceDate||'—');
  infoRow(d,CX+col3+3,     _y,col3,'Work Order:',  data.woNumber||'—');
  infoRow(d,CX+(col3+3)*2, _y,col3,'Technician:',  data.technicianName||'—');
  y=_y+ROW_H+GAP;
  y=infoRow(d,CX,y,CCW,'Asset Name:',data.assetName||'—');
  _y=y;
  infoRow(d,CX,       _y,half,'Asset ID:',data.assetId||'—');
  infoRow(d,CX+half+3,_y,half,'Location:',data.area||'—');
  y=_y+ROW_H+GAP+4;

  const baTabH=52;
  sideTab(d,y,baTabH,'Pre / Post Readings');
  const hw=(CCW-4)/2;
  card(d,CX,y,hw,46);
  rr(d,CX,y,hw,9,{r:3,fill:[255,248,225]});
  d.setDrawColor(...C.bdr); d.setLineWidth(0.3); d.line(CX,y+9,CX+hw,y+9);
  dot(d,CX+5,y+4.5,1.8,[184,134,11]);
  tx(d,'BEFORE MAINTENANCE',CX+10,y+6.5,{sz:8,bold:true,col:[184,134,11]});
  infoRow(d,CX+2,y+12,hw-4,'Vibration (in/s):',data.vibrationBefore||'—');
  infoRow(d,CX+2,y+25,hw-4,'Temperature (°F):', data.tempBefore||'—');
  const ax=CX+hw+4;
  card(d,ax,y,hw,46);
  rr(d,ax,y,hw,9,{r:3,fill:[232,245,233]});
  d.setDrawColor(...C.bdr); d.setLineWidth(0.3); d.line(ax,y+9,ax+hw,y+9);
  dot(d,ax+5,y+4.5,1.8,[46,125,50]);
  tx(d,'AFTER MAINTENANCE',ax+10,y+6.5,{sz:8,bold:true,col:[46,125,50]});
  infoRow(d,ax+2,y+12,hw-4,'Vibration (in/s):',data.vibrationAfter||'—');
  infoRow(d,ax+2,y+25,hw-4,'Temperature (°F):', data.tempAfter||'—');
  y+=52;

  sideTab(d,y,PH-y-20,'Maintenance Details');
  textCard(d,CX,y,CCW,46,'Maintenance Performed',data.maintenancePerformed||''); y+=50;
  textCard(d,CX,y,CCW,34,'Parts Replaced',data.partsReplaced||''); y+=38;
  textCard(d,CX,y,CCW,Math.max(PH-y-22,20),'Notes',data.notes||'');

  drawFooterBar(d,data.technicianName||'',data.maintenanceDate||'');
  drawPageFooter(d,id);
  d.save(id+'_Post_Maintenance.pdf');
  return id;
}

// ═══════════════════════════════════════════════════════════════════════════════
// RCFA
// ═══════════════════════════════════════════════════════════════════════════════
export function generateRCFAPDF(data, millName) {
  const d = new jsPDF({unit:'mm',format:'a4'});
  const id = 'RCFA-'+String(Math.floor(Math.random()*900)+100)+'-'+new Date().getFullYear();
  setFill(d,C.bg); d.rect(0,0,PW,PH,'F');
  drawHeader(d, 'Root Cause Failure Analysis', '5-Whys Methodology & Corrective Actions');

  const ROW_H=10, GAP=2;
  let y=42, col3=(CCW-6)/3, half=(CCW-3)/2;

  sideTab(d,y,52,'Event Information'); y+=2;
  let _y=y;
  infoRow(d,CX,            _y,col3,'Event Date:', data.eventDate||'—');
  infoRow(d,CX+col3+3,     _y,col3,'Work Order:', data.woNumber||'—');
  infoRow(d,CX+(col3+3)*2, _y,col3,'Analyst:',    data.analystName||'—');
  y=_y+ROW_H+GAP;
  _y=y;
  infoRow(d,CX,       _y,half,'Location:',        data.area||'—');
  infoRow(d,CX+half+3,_y,half,'Failed Component:', data.failedComponent||'—');
  y=_y+ROW_H+GAP+2;
  textCard(d,CX,y,CCW,28,'Problem Description',data.problemDescription||''); y+=32;

  sideTab(d,y,72,'5 Whys Analysis');
  const whyCols=[[198,40,40],[210,80,40],[215,120,30],[210,160,20],[184,134,11]];
  for (let i=1;i<=5;i++) {
    const wH=10, wc=whyCols[i-1];
    card(d,CX,y,CCW,wH,2);
    rr(d,CX,y,20,wH,{r:2,fill:[34,54,90]});
    rr(d,CX,y,2,wH,{r:0,fill:wc});
    tx(d,'WHY '+i,CX+4,y+wH/2+1,{sz:7.5,bold:true,col:C.white});
    d.setDrawColor(...C.bdr); d.setLineWidth(0.3); d.line(CX+20,y+1.5,CX+20,y+wH-1.5);
    tx(d,data['why'+i]||'—',CX+23,y+wH/2+1,{sz:8.5,col:C.txt});
    y+=wH+2;
    if (i<5){d.setDrawColor(...C.bdr);d.setLineWidth(0.4);d.line(CX+10,y,CX+10,y+2);setFill(d,C.bdr);d.triangle(CX+8.5,y+2,CX+11.5,y+2,CX+10,y+3.5,'F');y+=3.5;}
  }
  y+=4;

  sideTab(d,y,PH-y-20,'Root Cause & Actions');
  const rcH=28;
  card(d,CX,y,CCW,rcH);
  rr(d,CX,y,CCW,rcH,{r:3,fill:[253,236,234],stroke:[198,40,40],lw:0.6});
  rr(d,CX,y,CCW,9,{r:3,fill:[198,40,40]});
  rr(d,CX,y,2.5,9,{r:0,fill:C.white});
  tx(d,'ROOT CAUSE IDENTIFIED',CX+6,y+6.3,{sz:7.5,bold:true,col:C.white});
  d.setFont('helvetica','normal'); d.setFontSize(9); setFill(d,C.txt);
  d.splitTextToSize(data.rootCause||'',CCW-8).forEach((l,i)=>d.text(l,CX+4,y+14+i*5));
  y+=rcH+4;
  bulletCard(d,CX,y,CCW,Math.max(PH-y-22,28),'Corrective Actions',data.correctiveActions||'');

  drawFooterBar(d,data.analystName||'',data.eventDate||'');
  drawPageFooter(d,id);
  d.save(id+'_RCFA.pdf');
  return id;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Safety Form
// ═══════════════════════════════════════════════════════════════════════════════
export function generateSafetyPDF(data, millName) {
  const d = new jsPDF({unit:'mm',format:'a4'});
  const id = 'JSA-'+String(Math.floor(Math.random()*900)+100)+'-'+new Date().getFullYear();
  setFill(d,C.bg); d.rect(0,0,PW,PH,'F');
  drawHeader(d, 'Safety Form', 'Job Safety Analysis & PPE Checklist');

  const ROW_H=10, GAP=2;
  let y=42, col3=(CCW-6)/3, half=(CCW-3)/2;

  sideTab(d,y,52,'Job Information'); y+=2;
  let _y=y;
  infoRow(d,CX,            _y,col3,'Date:',     data.date||'—');
  infoRow(d,CX+col3+3,     _y,col3,'Location:', data.area||'—');
  infoRow(d,CX+(col3+3)*2, _y,col3,'Employee:', data.employeeName||'—');
  y=_y+ROW_H+GAP;
  _y=y;
  infoRow(d,CX,_y,half,'Supervisor:',data.supervisor||'—');
  y=_y+ROW_H+GAP+2;
  textCard(d,CX,y,CCW,26,'Task Description',data.taskDescription||''); y+=30;

  const ppeItems=[
    {key:'hardHat',label:'Hard Hat'},{key:'safetyGlasses',label:'Safety Glasses'},
    {key:'steelToeBoots',label:'Steel Toe Boots'},{key:'highVisVest',label:'High Vis Vest'},
    {key:'hearingProtection',label:'Hearing Protection'},{key:'gloves',label:'Gloves'},
    {key:'fallProtection',label:'Fall Protection'},{key:'faceShield',label:'Face Shield'},
  ];
  const ppeTab=40;
  sideTab(d,y,ppeTab,'PPE Checklist');
  const bw2=(CCW-6)/4, bh2=15;
  ppeItems.forEach(({key,label},i)=>{
    const col=i%4, rowN=Math.floor(i/4);
    const px=CX+col*(bw2+2), py=y+rowN*(bh2+2);
    const chkd=!!data[key];
    card(d,px,py,bw2,bh2,2);
    if (chkd) rr(d,px,py,bw2,bh2,{r:2,fill:[232,245,233],stroke:[46,125,50],lw:0.5});
    rr(d,px,py,2,bh2,{r:0,fill:chkd?[46,125,50]:C.bdr});
    rr(d,px+3.5,py+3.5,8,8,{r:1.5,fill:chkd?[46,125,50]:C.white,stroke:chkd?[46,125,50]:C.bdr,lw:0.4});
    if (chkd) tx(d,'✓',px+7.5,py+9.5,{sz:9,bold:true,col:C.white,align:'center'});
    tx(d,label,px+14,py+9,{sz:7.5,bold:chkd,col:chkd?[46,125,50]:C.muted});
  });
  y+=2*(bh2+2)+6;

  sideTab(d,y,PH-y-20,'Hazard Analysis');
  textCard(d,CX,y,CCW,40,'Hazards Identified',data.hazards||''); y+=44;
  textCard(d,CX,y,CCW,40,'Control Measures',data.controlMeasures||''); y+=44;

  const sigH=22, sw=(CCW-4)/2;
  card(d,CX,y,sw,sigH);
  cardHdr(d,CX,y,sw,9,'','EMPLOYEE SIGNATURE');
  d.setDrawColor(...C.bdr); d.setLineWidth(0.4); d.line(CX+5,y+sigH-4,CX+sw-5,y+sigH-4);
  tx(d,data.employeeName||'',CX+6,y+sigH-4.5,{sz:9,bold:true,col:C.blue});
  const sx2=CX+sw+4;
  card(d,sx2,y,sw,sigH);
  cardHdr(d,sx2,y,sw,9,'','SUPERVISOR SIGNATURE');
  d.setDrawColor(...C.bdr); d.setLineWidth(0.4); d.line(sx2+5,y+sigH-4,sx2+sw-5,y+sigH-4);
  tx(d,data.supervisor||'',sx2+6,y+sigH-4.5,{sz:9,bold:true,col:C.blue});

  drawPageFooter(d,id);
  d.save(id+'_Safety_Form.pdf');
  return id;
}
